template <typename UnionPtrType>
ExtraParamsPtr ExtraParams::Clone() const {
  switch (tag_) {
    case Tag::kNone:
      return NewNone(
          mojo::Clone(*data_.none));
    case Tag::kChannelQuant:
      return NewChannelQuant(
          mojo::Clone(*data_.channelQuant));
    case Tag::kExtension:
      return NewExtension(
          mojo::Clone(*data_.extension));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, ExtraParams>::value>::type*>
bool ExtraParams::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kNone:
      return mojo::Equals(*(data_.none), *(other.data_.none));
    case Tag::kChannelQuant:
      return mojo::Equals(*(data_.channelQuant), *(other.data_.channelQuant));
    case Tag::kExtension:
      return mojo::Equals(*(data_.extension), *(other.data_.extension));
  }

  return false;
}
